using System;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public partial class TV {
 Window floatingWindow;TVMirrorHost floatingHost;bool closingFloating=false,preferFloating=false;Button castToggle,floatToggle,recordToggle;TextBlock dropTitle,dropSubtitle;
 TVMirrorHost ActiveHost{get{return floatingHost??mirrorHost;}}
 Button ActionButton(Panel panel,string label,Action action){var button=new Button{Content=label,Padding=new Thickness(14,9,14,9),Margin=new Thickness(4),Background=Brushes.White,BorderBrush=Color("#DFE4EE")};if(label.Contains("开始投屏")){button.Tag="Primary";button.Background=AppleAccent();button.Foreground=Brushes.White;button.BorderBrush=Brushes.Transparent;}NormalizeActionButton(button,label);button.ToolTip=ButtonHelp(label);button.Click+=(s,e)=>{try{action();}catch(Exception ex){Report(ex.Message);}};panel.Children.Add(button);return button;}
 void ToggleCast(){Run(async()=>{if(Streaming)await StopMirror();else await StartMirror("");});}
 void ToggleFloating(){if(busy){Report("请等待当前任务结束。");return;}Run(async()=>{if(!Streaming){preferFloating=true;await StartMirror("");}else if(floatingWindow==null)await FloatMirror();else DockMirror();});}
 async Task FloatMirror(){if(!Streaming||floatingWindow!=null)return;var w=new Window{Title="瞎折腾 · 电视投屏",Icon=Icon,Width=1100,Height=720,MinWidth=640,MinHeight=420,Background=Color("#151B2B"),FontFamily=FontFamily,FontSize=13,Foreground=Foreground,WindowStartupLocation=WindowStartupLocation.CenterScreen};using(var theme=System.IO.File.OpenRead(Root+"Theme.xaml"))w.Resources.MergedDictionaries.Add((ResourceDictionary)System.Windows.Markup.XamlReader.Load(theme));var root=new DockPanel();ApplyMacChrome(w,root);var bar=new WrapPanel{Background=Color("#F5F6FA"),Margin=new Thickness(0)};DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);ActionButton(bar,"返回工作台",()=>DockMirror());ActionButton(bar,"停止投屏",()=>Run(async()=>await StopMirror()));ActionButton(bar,"截屏",()=>CaptureScreen());ActionButton(bar,"录屏",()=>ToggleRecording());var host=new TVMirrorHost();root.Children.Add(host);w.Closing+=(s,e)=>{if(closingFloating||closingStudio)return;e.Cancel=true;Dispatcher.BeginInvoke(new Action(()=>{try{DockMirror();}catch(Exception ex){Report(ex.Message);}}));};w.AllowDrop=true;w.Drop+=(s,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Handled=true;Install((string[])e.Data.GetData(DataFormats.FileDrop));}};w.Show();w.UpdateLayout();for(int i=0;host.Handle==IntPtr.Zero&&i<30;i++)await Task.Delay(20);if(host.Handle==IntPtr.Zero){closingFloating=true;w.Close();closingFloating=false;throw new Exception("独立投屏容器尚未就绪，请重试。");}var hwnd=mirrorHost.ReleaseVideo();if(hwnd==IntPtr.Zero){closingFloating=true;w.Close();closingFloating=false;throw new Exception("实时投屏画面未就绪");}floatingWindow=w;floatingHost=host;try{host.Attach(hwnd);}catch{floatingHost=null;floatingWindow=null;mirrorHost.Attach(hwnd);closingFloating=true;w.Close();closingFloating=false;throw;}preferFloating=true;mirrorHost.Visibility=Visibility.Collapsed;tvPlaceholder.Visibility=Visibility.Visible;UpdateMirrorState();}
 void DockMirror(){if(floatingWindow==null)return;Show("投屏工作台");mirrorHost.Visibility=Visibility.Visible;mirrorPage.UpdateLayout();IntPtr hwnd=floatingHost.ReleaseVideo();if(hwnd!=IntPtr.Zero)mirrorHost.Attach(hwnd);preferFloating=false;CloseFloating();tvPlaceholder.Visibility=Streaming?Visibility.Collapsed:Visibility.Visible;UpdateMirrorState();}
 void CloseFloating(){var w=floatingWindow;floatingWindow=null;floatingHost=null;if(w==null)return;closingFloating=true;try{w.Close();}finally{closingFloating=false;}}
}



